// Collect Audience Data | Mode: Run Once for All Items
// Gathers every verified fact the three audience briefs need into ONE item. Nothing here is written by an AI model.
// Sources (read by node name): Collect Report Data (facts), Check Sections (what is ready), Parse Blog Knowledge (article guidance),
// Encode to Base (the illustrations).
const safe = (fn, fallback) => { try { const v = fn(); return v === undefined || v === null ? fallback : v; } catch (e) { return fallback; } };
const arr = (v) => (Array.isArray(v) ? v : []);
const key = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, '');

const r = safe(() => $('Collect Report Data').first().json.report, {}) || {};
const checked = safe(() => $('Check Sections').first().json, {}) || {};
const know = safe(() => $('Parse Blog Knowledge').first().json.blogKnowledge, {}) || {};
const encoded = safe(() => $('Encode to Base').all().map((i) => i.json), []);
const products = r.products || {};
const social = r.social || {};

const segments = arr(r.segments).map((s) => ({
  n: s.n, name: String(s.name || ''), description: String(s.description || ''),
  visual_characteristics: arr(s.visual_characteristics), color_palette: arr(s.color_palette), typical_materials: arr(s.typical_materials),
  target_rooms: arr(s.target_rooms), price_positioning: s.price_positioning || null,
  support_level: ['stronger', 'moderate', 'weak', 'unverified'].includes(s.support_level) ? s.support_level : 'unverified',
  confidence: ['low', 'medium', 'high'].includes(s.confidence) ? s.confidence : 'low',
  weakest_attribute: s.weakest_attribute || null,
  verified_signals: arr(s.trend_signals).filter((t) => !/^AI note:/i.test(String(t))).slice(0, 4),   // counts only: the AI's own notes are left out
  suggested_action: s.suggested_action || '',
}));

// one illustration per segment, matched by name first and by position second; only valid base64 is kept
const images = segments.map((s, idx) => {
  const match = encoded.find((e) => key(e.segmentName) === key(s.name)) || (encoded.length === segments.length ? encoded[idx] : null);
  const b64 = match && match.hasImage ? String(match.base64Image || '').replace(/\s+/g, '') : '';
  const valid = b64.length > 20 && /^[A-Za-z0-9+/]+={0,2}$/.test(b64);
  const mime = match && /^image\/(jpeg|png|webp)$/.test(String(match.mimeType)) ? match.mimeType : 'image/jpeg';
  return { n: s.n, name: s.name, mimeType: valid ? mime : null, base64: valid ? b64 : null };
});

const iso = /^\d{4}-\d{2}-\d{2}$/.test(String(r.generated_on || checked.generated_on)) ? (r.generated_on || checked.generated_on) : new Date().toISOString().slice(0, 10);
const date = new Date(`${iso}T00:00:00Z`).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC' });
const dates = social.post_dates || {};
const ages = ['instagram', 'pinterest'].map((k) => dates[k] && dates[k].newest_age_days).filter((x) => Number.isFinite(x));

const knowledge = {
  sizing_rules: arr(know.sizing && know.sizing.rules), sizing_by_room: { living_room: (know.sizing || {}).living_room || null, bedroom: (know.sizing || {}).bedroom || null, dining: (know.sizing || {}).dining || null },
  durability: (know.materials || {}).durability || {}, care_needs: (know.materials || {}).care_needs || {},
  trending: arr((know.style_insights || {}).trending), color_advice: (know.style_insights || {}).color_advice || null,
  quality_indicators: arr((know.buyer_guidance || {}).quality_indicators),
  evidence: arr(know.evidence).map((e) => ({ field: e.field, key: e.key, text: e.text, source_id: e.source_id })),
  market_figures: arr(know.market_figures).map((f) => ({ figure: f.figure, type: f.type, source_id: f.source_id, context: String(f.context || '').slice(0, 120) })),
};

return [{
  json: {
    facts: {
      category: String(r.category || checked.category || 'Rug'), date, isoDate: iso,
      products: { analyzed: products.products_analyzed || 0, returned: products.products_returned || null, price: products.price || null, price_distribution: products.price_distribution || {}, rating: products.rating || null, top: products.top || {} },
      social: { posts: social.posts_analyzed || 0, instagram: social.instagram_posts || 0, pinterest: social.pinterest_posts || 0, post_dates: dates, top_hashtags: arr(social.top_hashtags).slice(0, 8), newest_age_min: ages.length ? Math.min(...ages) : null, newest_age_max: ages.length ? Math.max(...ages) : null, amazon_age_days: safe(() => social.snapshots.amazon.age_days, null), sources_unavailable: arr(social.sources_unavailable) },
      comparison: arr(r.comparison),
      segments,
      knowledge,
      quality: { warnings: arr(r.warnings), articles: safe(() => r.run_status.blog_documents, 0) + safe(() => r.run_status.market_documents, 0), report_ready: checked.ready === true, failed_sections: arr(checked.failed_sections), review_sections: arr(checked.sections_needing_review) },
    },
    images,
  },
}];

