// Check Creative Brief | Mode: Run Once for All Items
// The model writes JSON only; this node never lets raw model text into the page.
//  - the answer is parsed (fenced JSON and JSON with words around it are read)
//  - every string is cut to length, stripped of tags, and DROPPED if it states a number that is not in the facts,
//    or claims proven demand, performance or preference
//  - problems give a status and an empty brief, never a crash: the marketing page then says the ideas were not generated
const safe = (fn, fallback) => { try { const v = fn(); return v === undefined || v === null ? fallback : v; } catch (e) { return fallback; } };
const arr = (v) => (Array.isArray(v) ? v : []);
const facts = safe(() => $('Collect Audience Data').first().json.facts, {}) || {};
const segN = new Set(arr(facts.segments).map((s) => Number(s.n)));

const input = $input.first().json;
let out = input.output;
const done = (status, creative, dropped) => [{ json: { creative, creativeStatus: status, droppedStrings: dropped || 0 } }];
const empty = { themes: [], segments: [], content_tests: [] };
if (input.error !== undefined || out === undefined || out === null || (typeof out === 'string' && out.trim() === '')) return done('ai_unavailable', empty);
if (typeof out === 'string') {
  out = out.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  try { out = JSON.parse(out); } catch (e) {
    const a = out.indexOf('{'); const b = out.lastIndexOf('}');
    try { out = JSON.parse(out.slice(a, b + 1)); } catch (e2) { return done('ai_output_invalid', empty); }
  }
}
if (!out || typeof out !== 'object' || Array.isArray(out)) return done('ai_output_invalid', empty);

// numbers that exist in the facts: anything else is dropped (whole numbers 0 to 10 are plain words)
const dropCommas = (t) => String(t).replace(/(?<=\d),(?=\d{3})/g, '');
const known = new Set((dropCommas(JSON.stringify(facts)).match(/\d+(?:\.\d+)?/g) || []).map((x) => String(Number(x))));
const BAD = /\b(proven|guarantee[sd]?|will (?:increase|boost|drive|double|grow|sell)|best-?sell\w*|skyrocket\w*|viral|surging|booming|(?:customers?|consumers?|shoppers?|buyers?|people)(?: \w+){0,2} (?:prefer|want|love|choose)s?|(?:strong|high|growing|rising|huge|massive) demand|demand (?:is|are|has|was|will)|popular(?:ity)?|market leader|number one)\b/i;
let dropped = 0;
const text = (s, n) => {
  const t = String(s ?? '').replace(/<[^>]*>/g, ' ').replace(/[‐‑]/g, '-').replace(/\s+/g, ' ').trim().slice(0, n);
  if (t.length < 3) return null;
  const unknown = (dropCommas(t).match(/\d+(?:\.\d+)?/g) || []).filter((x) => !(Number.isInteger(Number(x)) && Number(x) <= 10) && !known.has(String(Number(x))));
  if (unknown.length || BAD.test(t)) { dropped++; return null; }
  return t;
};
const list = (v, n, len) => arr(v).slice(0, n).map((x) => text(x, len)).filter(Boolean);

const creative = {
  themes: arr(out.themes).slice(0, 3).map((t) => ({ name: text(t && t.name, 60), idea: text(t && t.idea, 220), segments: arr(t && t.segments).map(Number).filter((n) => segN.has(n)) })).filter((t) => t.name && t.idea),
  segments: arr(out.segments).slice(0, 3).map((s) => ({
    n: Number(s && s.n), audience_hypothesis: text(s && s.audience_hypothesis, 220), key_message: text(s && s.key_message, 160), tone: text(s && s.tone, 80),
    content_ideas: list(s && s.content_ideas, 3, 160), test_to_run: text(s && s.test_to_run, 200),
  })).filter((s) => segN.has(s.n)),
  content_tests: arr(out.content_tests).slice(0, 3).map((t) => ({ test: text(t && t.test, 200), measure: text(t && t.measure, 120) })).filter((t) => t.test),
};
const total = creative.themes.length + creative.segments.length + creative.content_tests.length;
return done(total ? (dropped ? 'partial' : 'ok') : 'no_usable_ideas', total ? creative : empty, dropped);

// Build Audience Briefs | Mode: Run Once for All Items
// Builds three self-contained HTML pages from verified facts (no external fonts, scripts or links; everything inserted is escaped):
//   A  Supplier and product development: concept briefs, each specification next to its real counts, priorities, specs to validate (code only)
//   B  Marketing and creative: creative briefs and campaign ideas as IDEAS TO TEST (the model's JSON, filtered by Check Creative Brief)
//   C  Leadership and decision-makers: decision brief with an evidence-confidence indicator per recommendation (code only)
const safe = (fn, fallback) => { try { const v = fn(); return v === undefined || v === null ? fallback : v; } catch (e) { return fallback; } };
const arr = (v) => (Array.isArray(v) ? v : []);
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const aud = safe(() => $('Collect Audience Data').first().json, {}) || {};
const F = aud.facts || {};
const images = arr(aud.images);
const cre = safe(() => $('Check Creative Brief').first().json, null) || { creative: { themes: [], segments: [], content_tests: [] }, creativeStatus: 'ai_unavailable' };
const creative = cre.creative || { themes: [], segments: [], content_tests: [] };

const P = F.products || {}; const S = F.social || {}; const segs = arr(F.segments); const K = F.knowledge || {}; const Q = F.quality || {};
const N = P.analyzed || 0; const M = S.posts || 0;
const category = F.category || 'Rug';
const LEVEL = { stronger: 4, moderate: 3, weak: 2, unverified: 1 };
const lvl = (s) => LEVEL[s.support_level] || 1;
const sorted = [...segs].sort((a, b) => lvl(b) - lvl(a));
const money = (n) => (n === null || n === undefined ? 'n/a' : `$${Number(n).toFixed(2)}`);
const meter = (level) => `<span class="meter" title="evidence ${LEVEL[level] || 1} of 4">${[1, 2, 3, 4].map((i) => `<i${i <= (LEVEL[level] || 1) ? ' class="on"' : ''}></i>`).join('')}</span> <span class="muted">${esc(level)} (${LEVEL[level] || 1}/4)</span>`;
const img = (n) => images.find((i) => Number(i.n) === Number(n) && i.base64);
const figure = (i) => `<figure class="moodboard"><img src="data:${i.mimeType};base64,${i.base64}" alt="AI-generated illustration of the ${esc(i.name)} style"><figcaption>${esc(i.name)}: AI-generated illustration of the style, not a product photo</figcaption></figure>`;
const ul = (items) => (items.length ? `<ul>${items.map((x) => `<li>${x}</li>`).join('')}</ul>` : '');
const table = (head, rows) => `<table><thead><tr>${head.map((h) => `<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;

// ---------- shared page frame ----------
const CSS = [
  ':root { --primary:#7C3AED; --light:#A78BFA; --text:#1F2937; --muted:#6B7280; --bg:#F9FAFB; --card:#fff; --border:#E5E7EB; --warn:#92400E; --warnbg:#FEF3C7; }',
  '* { margin:0; padding:0; box-sizing:border-box; }',
  'body { font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; font-size:14px; line-height:1.6; color:var(--text); background:var(--bg); }',
  '.wrap { max-width:1000px; margin:0 auto; padding:36px 24px; }',
  'header.top { background:linear-gradient(135deg,var(--primary),#5B21B6); color:#fff; padding:38px 36px; border-radius:16px; margin-bottom:22px; }',
  'header.top h1 { font-size:27px; margin-bottom:6px; } header.top .q { font-size:15px; opacity:.92; } header.top .meta { margin-top:12px; font-size:12px; opacity:.85; }',
  '.banner { background:var(--warnbg); color:var(--warn); border-left:4px solid #F59E0B; border-radius:8px; padding:12px 16px; margin-bottom:20px; }',
  '.callout { background:#EDE9FE; border-left:4px solid var(--primary); border-radius:8px; padding:16px 18px; margin-bottom:8px; }',
  'section { background:var(--card); border-radius:12px; padding:28px; margin-bottom:20px; box-shadow:0 1px 3px rgba(0,0,0,.1); }',
  'section h2 { font-size:20px; margin-bottom:16px; padding-bottom:10px; border-bottom:2px solid var(--light); } section h3 { font-size:16px; color:var(--primary); margin:18px 0 8px; }',
  'p { margin-bottom:10px; } ul, ol { margin:0 0 12px 22px; } li { margin-bottom:5px; } .muted { color:var(--muted); font-size:12px; }',
  'table { width:100%; border-collapse:collapse; margin:10px 0 16px; font-size:13px; } th, td { border:1px solid var(--border); padding:7px 9px; text-align:left; vertical-align:top; } th { background:#F3F4F6; }',
  '.badge { display:inline-block; padding:2px 8px; border-radius:10px; font-size:11px; font-weight:600; background:#E5E7EB; } .b-go { background:#D1FAE5; color:#065F46; } .b-hold { background:#FEF3C7; color:#92400E; } .b-stop { background:#FEE2E2; color:#991B1B; }',
  '.meter i { display:inline-block; width:12px; height:12px; margin-right:2px; border-radius:2px; background:#E5E7EB; } .meter i.on { background:var(--primary); }',
  'figure.moodboard { margin:12px 0; border:1px solid var(--border); border-radius:12px; overflow:hidden; } figure.moodboard img { display:block; width:100%; height:auto; max-height:420px; object-fit:cover; } figure.moodboard figcaption { padding:8px 12px; font-size:12px; color:var(--muted); }',
  '.card { border:1px solid var(--border); border-radius:10px; padding:18px; margin-bottom:16px; background:#FCFCFD; }',
  '.foot { text-align:center; padding:22px; color:var(--muted); font-size:12px; }',
  '@media (max-width:768px) { section { padding:18px; } table { display:block; overflow-x:auto; } }',
  '@media print { body { background:#fff; } section { box-shadow:none; break-inside:avoid-page; } }',
].join('\n');
const gaps = [...arr(Q.failed_sections), ...arr(Q.review_sections)];
const banner = gaps.length ? `<div class="banner"><strong>Source report incomplete.</strong> These sections of the main report failed or need review: ${gaps.map(esc).join(', ')}. Check them before relying on this brief.</div>` : '';
const page = (id, title, question, body, footNote) => '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">' +
  `<title>${esc(category)}: ${esc(title)}</title><style>${CSS}</style></head><body><div class="wrap">` +
  `<header class="top"><h1>${esc(category)}: ${esc(title)}</h1><p class="q">${esc(question)}</p><p class="meta">Generated: ${esc(F.date)} | Based on ${N} products, ${M} social posts and ${Q.articles || 0} articles | Retail Market Trend Discovery workflow</p></header>` +
  banner + `<main id="${id}">${body}</main><footer class="foot"><p>${esc(footNote)}</p></footer></div></body></html>`;

// ---------- evidence helpers (counts come from the comparison the workflow matched) ----------
const cmp = {}; for (const g of arr(F.comparison)) cmp[g.group] = arr(g.values);
const nrm = (s) => String(s ?? '').toLowerCase().replace(/[_-]+/g, ' ').replace(/\bpile\b/g, '').replace(/\s+/g, ' ').trim();
const rowsFor = (group, text) => arr(cmp[group]).filter((r) => { const v = nrm(r.value); if (!v) return false; const stem = (v.length > 5 ? v.slice(0, 5) : v).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); return new RegExp(`\\b${stem}`).test(nrm(text)); });
const countText = (r) => `${esc(r.value)}: ${r.amazon_products !== null ? `${r.amazon_products} of ${N} products` : 'not among the listed products'}; ${r.social_posts !== null ? `${r.social_posts} of ${M} posts` : 'not among the listed posts'}`;
const statusOf = (rows) => {
  if (!rows.length) return { label: 'No count: a model suggestion, validate', cls: 'b-stop' };
  const both = rows.filter((r) => r.amazon_products !== null && r.social_posts !== null).length;
  const aOnly = rows.filter((r) => r.amazon_products !== null && r.social_posts === null).length;
  const sOnly = rows.filter((r) => r.amazon_products === null && r.social_posts !== null).length;
  if (both === rows.length) return { label: 'Seen in products and posts', cls: 'b-go' };
  if (aOnly === rows.length) return { label: 'Seen in products only', cls: 'b-hold' };
  if (sOnly === rows.length) return { label: 'Seen in posts only', cls: 'b-hold' };
  return { label: 'Mixed: some values seen in both, others in one source only', cls: 'b-hold' };
};
const buckets = Object.entries(P.price_distribution || {}).filter(([, c]) => c > 0);
const bucketText = buckets.map(([b, c]) => `${esc(b)}: ${c} of ${N} products`).join('; ') || 'not available';
const guidance = (prefixes) => arr(K.evidence).filter((e) => prefixes.some((p) => String(e.field).startsWith(p)));

// =====================================================================================================
// C  LEADERSHIP
// =====================================================================================================
const best = sorted[0];
const supported = sorted.filter((s) => lvl(s) >= 3);
const headline = supported.length
  ? `Run a small, time-boxed test on ${supported.map((s) => esc(s.name)).join(' and ')}; validate the other segment(s) before investing.`
  : 'Do not commit investment on this evidence. No segment has more than weak support, so validate first (sales data, fresh social data, customer research).';
const overall = best ? best.support_level : 'unverified';
const stance = (s) => (lvl(s) >= 3 ? '<span class="badge b-go">Test</span>' : lvl(s) === 2 ? '<span class="badge b-hold">Hold: validate</span>' : '<span class="badge b-stop">Do not act</span>');
const ageText = S.newest_age_min === null ? 'not available' : (S.newest_age_min === S.newest_age_max ? `${S.newest_age_min} days` : `${S.newest_age_min} to ${S.newest_age_max} days`);
const leadership = (() => {
  const d = [];
  d.push(`<section id="decision"><h2>The decision</h2><div class="callout"><strong>Recommendation:</strong> ${headline}<br><span class="muted">Overall evidence confidence: </span>${meter(overall)}<br><span class="muted">Confidence is capped at medium: the data is a small, dated, curated snapshot.</span></div></section>`);
  d.push(`<section id="segments"><h2>Segment comparison</h2>${segs.length ? table(['Segment', 'Evidence', 'Verified signals', 'Weakest attribute', 'Recommended action', 'Stance'], sorted.map((s) => [`<strong>${esc(s.name)}</strong><br><span class="muted">${esc(arr(s.target_rooms).join(', '))}</span>`, meter(s.support_level) + `<br><span class="muted">confidence: ${esc(s.confidence)}</span>`, ul(s.verified_signals.slice(0, 3).map(esc)) || '<span class="muted">none</span>', esc(s.weakest_attribute || 'not available'), esc(s.suggested_action), stance(s)])) : '<p>No segments were identified.</p>'}</section>`);
  d.push(`<section id="quality"><h2>Data quality: how far to trust this</h2>${ul([
    `<strong>Products:</strong> ${N} analysed${P.returned ? ` of ${P.returned} returned` : ''}; Amazon snapshot ${S.amazon_age_days === null ? 'age not available' : `${S.amazon_age_days} days old`}.`,
    `<strong>Social posts:</strong> ${M} (${S.instagram} Instagram, ${S.pinterest} Pinterest); the newest are ${esc(ageText)} old, so they show past interest, not current trends.`,
    `<strong>Articles:</strong> ${Q.articles || 0}. Their market figures are reported by the articles and not verified.`,
    `<strong>Not available:</strong> sales, traffic and search-volume data. Nothing in this brief measures demand.`,
    ...(arr(S.sources_unavailable).length ? [`<strong>Sources that failed:</strong> ${arr(S.sources_unavailable).map(esc).join(', ')}.`] : []),
  ])}${arr(Q.warnings).length ? `<h3>Warnings raised by the workflow</h3>${ul(arr(Q.warnings).map(esc))}` : ''}</section>`);
  d.push(`<section id="pricing"><h2>Pricing observations</h2>${ul([
    P.price ? `Observed prices (${P.price.n} products): minimum ${money(P.price.min)}, median ${money(P.price.median)}, maximum ${money(P.price.max)}.` : 'Observed prices: not available.',
    `By price bucket: ${bucketText}.`,
    P.rating ? `Average rating: ${P.rating.mean} (${P.rating.n} products).` : 'Average rating: not available.',
    `Segment price tiers (${segs.map((s) => `${esc(s.name)}: ${esc(s.price_positioning || 'n/a')}`).join('; ') || 'none'}) are the model's estimates and are not validated against prices.`,
  ])}<p class="muted">Prices are what was listed in one snapshot; they are not a recommendation for a selling price.</p></section>`);
  // a group is "concentrated" only when its most common value covers at least 60% of the sample
  const conc = ['material', 'size', 'color', 'style'].map((g) => { const t = arr((P.top || {})[g])[0]; return t && N && t.count / N >= 0.6 ? `${esc(t.value)} in ${t.count} of ${N} products` : null; }).filter(Boolean);
  d.push(`<section id="risks"><h2>Commercial risks</h2>${ul([
    `<strong>Small sample.</strong> ${N} products and ${M} posts: rankings can change with a few items.`,
    `<strong>Old signals.</strong> Social posts are ${esc(ageText)} old${S.amazon_age_days === null ? '' : ` and the Amazon snapshot is ${S.amazon_age_days} days old`}.`,
    `<strong>No sales evidence.</strong> A segment can look interesting in posts and not sell.`,
    ...(conc.length ? [`<strong>Concentrated sample.</strong> ${conc.join('; ')}; findings may not hold for the wider assortment.`] : []),
    `<strong>AI-labelled attributes.</strong> Product attributes were read from listing text by an AI model and checked against keywords.`,
    `<strong>Illustrations are not products.</strong> The images are AI-generated moodboards.`,
  ])}</section>`);
  d.push(`<section id="next"><h2>Recommended next steps</h2>${table(['Step', 'Evidence it would add', 'Decision it informs'], [
    ['Obtain recent sales and traffic data for this category', 'Whether any segment actually sells', 'Whether any segment should get investment'],
    ['Refresh the social snapshot with a larger, current set of posts', 'Whether the signals still hold today', 'Whether to keep or drop the weak segments'],
    ['Run customer research (surveys or interviews) on the candidate styles', 'What customers say, not what hashtags suggest', 'Which style to brief to suppliers and creative'],
    ...(supported.length ? [[`Develop a small sample set for ${supported.map((s) => esc(s.name)).join(' and ')}`, 'Whether suppliers can meet the specification', 'Whether to scale the test']] : [['Hold product development', 'Nothing to test yet: no segment has moderate support', 'Revisit after the evidence above']]),
  ])}</section>`);
  const figs = arr(K.market_figures).filter((f) => f.type === 'money amount').slice(0, 4);
  if (figs.length) d.push(`<section id="context"><h2>Market context (reported by articles, not verified)</h2>${ul(figs.map((f) => `${esc(f.figure)} (${esc(f.source_id)}): ${esc(f.context)}`))}</section>`);
  return d.join('\n');
})();

