const marketing = (() => {
  const d = [];
  d.push(`<section id="read"><h2>How to read this brief</h2><div class="callout"><strong>These are ideas to test, not proven consumer preferences.</strong> The data is a small, dated snapshot of ${M} posts with no sales or engagement results for any campaign. Each segment shows how much evidence stands behind it.</div></section>`);
  const cs = new Map(arr(creative.segments).map((s) => [Number(s.n), s]));
  const cards = sorted.map((s) => {
    const c = cs.get(Number(s.n)); const im = img(s.n);
    return `<div class="card"><h3>${esc(s.name)}</h3><p class="muted">Evidence behind this style: ${meter(s.support_level)} | ${esc(s.suggested_action)}</p>${im ? figure(im) : ''}<p>${esc(s.description)}</p>` +
      (c ? `<h4>Creative brief (idea to test)</h4>${ul([c.audience_hypothesis && `<strong>Audience hypothesis:</strong> ${esc(c.audience_hypothesis)}`, c.key_message && `<strong>Key message:</strong> ${esc(c.key_message)}`, c.tone && `<strong>Tone:</strong> ${esc(c.tone)}`].filter(Boolean))}${c.content_ideas.length ? `<p><strong>Content ideas</strong></p>${ul(c.content_ideas.map(esc))}` : ''}${c.test_to_run ? `<p><strong>Test to run:</strong> ${esc(c.test_to_run)}</p>` : ''}` : '<p class="muted">Creative ideas were not generated for this segment.</p>') +
      `<p class="muted">What the data supports: ${esc(s.verified_signals.slice(0, 3).join('; ') || 'no verified count')}. Weakest attribute: ${esc(s.weakest_attribute || 'not available')}.</p></div>`;
  });
  d.push(`<section id="styles"><h2>The three visual styles</h2>${cards.join('') || '<p>No segments were identified.</p>'}</section>`);
  if (arr(creative.themes).length) d.push(`<section id="themes"><h2>Campaign themes (ideas to test)</h2>${ul(creative.themes.map((t) => `<strong>${esc(t.name)}:</strong> ${esc(t.idea)}${t.segments.length ? ` <span class="muted">(styles: ${t.segments.map((n) => esc((segs.find((x) => Number(x.n) === n) || {}).name || n)).join(', ')})</span>` : ''}`))}</section>`);
  if (arr(creative.content_tests).length) d.push(`<section id="tests"><h2>Content tests to run</h2>${table(['Test', 'What to measure'], creative.content_tests.map((t) => [esc(t.test), esc(t.measure || 'to be defined')]))}</section>`);
  if (!arr(creative.themes).length && !arr(creative.segments).length) d.push(`<section id="status"><h2>Creative ideas</h2><p>The creative ideas could not be generated in this run (${esc(cre.creativeStatus)}). The facts above are unaffected. Run the Creative Brief Generator again to add them.</p></section>`);
  d.push(`<section id="hashtags"><h2>Hashtags seen in the sample</h2><p class="muted">Counts are posts in the sample that used the tag. They are an observation about ${M} older posts, not a prediction of performance.</p>${table(['Hashtag', `Posts (of ${M})`], arr(S.top_hashtags).map((h) => [esc(h.tag), String(h.count)]))}</section>`);
  const claimsTrend = arr(K.trending);
  if (claimsT(claimsTrend)) d.push(`<section id="articles"><h2>What the articles say about style and colour</h2>${ul([...claimsTrend.map(esc), ...(K.color_advice ? [esc(K.color_advice)] : [])])}<p class="muted">Claims quoted from trade articles (verified against the article text), not customer research.</p></section>`);
  return d.join('\n');
  function claimsT(a) { return a.length || K.color_advice; }
})();

const slug = category.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '') || 'rug';
const mk = (audience, label, id, title, question, body, foot) => ({ json: { audience, label, fileName: `${slug}_${audience}_brief_${F.isoDate}.html`, html: page(id, title, question, body, foot) } });
return [
  mk('supplier', 'Supplier and Product Development', 'supplier', 'Supplier and product development brief', 'What should we consider developing or sourcing?', supplier, 'Counts describe a small sample and are not market totals. Specifications without a count are model suggestions and must be validated.'),
  mk('marketing', 'Marketing and Creative', 'marketing', 'Marketing and creative brief', 'What should we communicate, and how?', marketing, 'Everything in this brief is an idea to test, not a proven consumer preference. Illustrations are AI-generated.'),
  mk('leadership', 'Leadership and Decision-Makers', 'leadership', 'Leadership decision brief', 'Where should we focus resources, and what evidence is missing?', leadership, 'Evidence confidence is capped at medium: the data is a small, dated, curated snapshot with no sales data.'),
];

// Audience Brief Validator | Mode: Run Once for All Items
// Checks each of the three pages for what that audience needs and for safety. isValid is true only when nothing is wrong.
const safe = (fn, fallback) => { try { const v = fn(); return v === undefined || v === null ? fallback : v; } catch (e) { return fallback; } };
const arr = (v) => (Array.isArray(v) ? v : []);
const aud = safe(() => $('Collect Audience Data').first().json, {}) || {};
const nSeg = arr(aud.facts && aud.facts.segments).length;
const expectedImages = arr(aud.images).filter((i) => i && i.base64).length;

const NEED = {
  supplier: ['how', 'assortment', 'concepts', 'priorities', 'validate', 'claims', 'bands'],
  marketing: ['read', 'styles', 'hashtags'],
  leadership: ['decision', 'segments', 'quality', 'pricing', 'risks', 'next'],
};
return $input.all().map((item) => {
  const j = item.json; const html = String(j.html || ''); const w = []; const miss = [];
  for (const id of NEED[j.audience] || []) if (!new RegExp(`<section id="${id}">`).test(html)) miss.push(id);
  if (miss.length) w.push(`Missing sections: ${miss.join(', ')}`);
  if (!/^<!DOCTYPE html>/.test(html) || !/<\/html>\s*$/.test(html)) w.push('The HTML is incomplete');
  if (/<script\b/i.test(html)) w.push('The page contains a script tag');
  if (/(?:src|href)\s*=\s*"https?:\/\//i.test(html) || /@import|googleapis/i.test(html)) w.push('The page loads something from the internet');
  if (/\[\[|\{\{/.test(html)) w.push('A placeholder was left in the text');
  const imgs = (html.match(/<img\s[^>]*src="data:image\/(?:jpeg|png|webp);base64,/g) || []).length;
  if (j.audience === 'marketing') {
    if (!/ideas to test, not proven consumer preferences/i.test(html)) w.push('The "ideas to test" notice is missing');
    if (imgs < expectedImages) w.push(`Only ${imgs} of ${expectedImages} images were embedded`);
  }
  if (j.audience === 'supplier' && (html.match(/class="card"/g) || []).length < nSeg) w.push('A segment has no concept brief');
  if (j.audience === 'leadership' && (html.match(/class="meter"/g) || []).length < nSeg + 1) w.push('An evidence indicator is missing');
  if (nSeg === 0) w.push('No trend segments were available');
  if (html.length > 15 * 1024 * 1024) w.push('The page is larger than 15 MB');
  const hard = w.filter((x) => !/No trend segments/.test(x));
  return { json: { ...j, validation: { isValid: hard.length === 0 && nSeg > 0, imageCount: imgs, expectedImages: j.audience === 'marketing' ? expectedImages : 0, warnings: w } } };
});

// Download Audience Briefs | Mode: Run Once for All Items
// One downloadable .html file per audience (Binary > data), each with its validation result.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const buffer = Buffer.from(String(j.html || ''), 'utf8');
  let bin;
  try {
    bin = await this.helpers.prepareBinaryData(buffer, j.fileName, 'text/html');
  } catch (e) {
    bin = { data: buffer.toString('base64'), mimeType: 'text/html', fileName: j.fileName };
  }
  out.push({ json: { audience: j.audience, label: j.label, fileName: j.fileName, sizeKB: Math.round(buffer.length / 1024), validation: j.validation, ready: !!(j.validation && j.validation.isValid) }, binary: { data: bin } });
}
return out;
